        classes = [[] for _ in range(nc)]
        for v in range(n):
            classes[colors[v]].append(v)
        classes.sort(key=len)
        for cls in classes:
            cls.sort(key=lambda v: degree[v], reverse=True)
        return [v for cls in classes for v in cls]

    best = reduce(dsatur_color())
    best_k = max(best) + 1

    no_improve = 0
    for it in range(50):
        if best_k <= 2 or no_improve >= 15:
            break
        if it % 3 == 0:
            order = make_order(best)
        elif it % 3 == 1:
            order = sorted(range(n), key=lambda v: degree[v], reverse=True)
        else:
            order = make_order(best)
            random.shuffle(order[:min(n//4+1, n)])
        candidate = reduce(greedy_color(order))
        k = max(candidate) + 1
        if k < best_k:
            best_k, best, no_improve = k, candidate, 0
        else:
            no_improve += 1
        # Also try randomized dsatur occasionally
        if it % 5 == 4:
            candidate2 = reduce(dsatur_color(shuffle=True))
            k2 = max(candidate2) + 1
            if k2 < best_k:
                best_k, best, no_improve = k2, candidate2, 0

    return best
